def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if not line.strip():
            continue
        # Split on first '=' only
        if '=' not in line:
            raise ValueError("Missing '=' in line: " + line)
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        # Reject empty key
        if not key:
            raise ValueError("Empty key in line: " + line)
        result[key] = value
    return result

