def summarize_usage(events):
    # Track max input and output counts per request_id
    max_input = {}
    max_output = {}

    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        # Reject negative counts
        if input_count < 0:
            raise ValueError("Negative input count is not allowed")
        if output_count < 0:
            raise ValueError("Negative output count is not allowed")

        # Keep maximum seen counts independently per request
        if request_id not in max_input or input_count > max_input[request_id]:
            max_input[request_id] = input_count
        if request_id not in max_output or output_count > max_output[request_id]:
            max_output[request_id] = output_count

    # Sum across all requests
    total_input = 0
    for v in max_input:
        total_input = total_input + max_input[v]
    total_output = 0
    for v in max_output:
        total_output = total_output + max_output[v]

    return {'input': total_input, 'output': total_output}

